#[derive(Clone, Copy, Debug)]
pub struct Subsystem {
    pub name: &'static str,
    pub directive_section: u16,
    pub summary: &'static str,
}

pub const SUBSYSTEMS: &[Subsystem] = &[
    Subsystem {
        name: "Diagnostics",
        directive_section: 33,
        summary: "Coded, located, actionable diagnostics with severity and origin.",
    },
    Subsystem {
        name: "The language of refusals",
        directive_section: 33,
        summary: "Every sentence and every context label a diagnostic can carry is \
                  looked up in the language the caller asked for, with the English \
                  kept beside it, and a gate check refuses a new diagnostic that \
                  has no line in a language this speaks.",
    },
    Subsystem {
        name: "Package seal",
        directive_section: 26,
        summary: "A class carrying the signing certificate's fingerprint is compiled \
                  into every package this builds and declared as a provider, so it \
                  runs before the application does and refuses to start a copy that \
                  a different key signed.",
    },
    Subsystem {
        name: "Capability security",
        directive_section: 7,
        summary: "Default-deny capability policy with an audit record per request.",
    },
    Subsystem {
        name: "SHA-2",
        directive_section: 30,
        summary: "FIPS 180-4 SHA-256, SHA-384 and SHA-512, each verified against \
                  the published NIST vectors including the long-message one.",
    },
    Subsystem {
        name: "Virtual filesystem",
        directive_section: 8,
        summary: "Named mounts, normalised paths, traversal and symlink refusal, \
                  quotas, atomic writes.",
    },
    Subsystem {
        name: "Project model",
        directive_section: 44,
        summary: "Omni.toml parsed, validated and reduced to a configuration digest over a canonical encoding: every part length-prefixed so no value can be read as a separator, and every unordered part sorted so the same facts always come to the same bytes. What the encoding writes can be read back to what went in, which is the same claim as no two projects sharing a digest, said in a way a test can check.",
    },
    Subsystem {
        name: "Artifact lifecycle",
        directive_section: 58,
        summary: "CREATED to PUBLISHED as a state machine that refuses illegal steps, over a store that keeps what a build produced. Objects are named by what is in them, so identical output is kept once; they are written under a temporary name and moved over the final one, so a machine that stops leaves either nothing or the whole thing; and a read checks what came back against the name it asked for, removing and reporting anything that no longer matches. A sweep brings the store to a budget, taking what was wanted longest ago first and stepping around anything leased.",
    },
    Subsystem {
        name: "Incremental cache",
        directive_section: 11,
        summary: "Cache keys over every input directive section 11 names, taken over a canonical encoding so that an environment variable holding a separator cannot be written to look like two, and four distinguishable lookup outcomes. The index is written down and read back, beside itself and then moved over itself, and it says what each key stands for so a hit hands back the bytes rather than only the news that a key was seen. An index that outlives what it indexes is reconciled against the store; one that cannot be read is an empty one, because refusing to start over a damaged cache file would turn something harmless into something fatal.",
    },
    Subsystem {
        name: "Build graph",
        directive_section: 9,
        summary: "A real DAG with deterministic ordering and cycle detection.",
    },
    Subsystem {
        name: "Scheduler",
        directive_section: 10,
        summary: "Executes a graph across as many lanes as the machine can afford, propagates failure, honours cancellation, and picks a build up where the last one stopped. Work whose dependencies have all produced their outputs is handed to whichever lane is free, so a fan of steps that wait on nothing runs at once; what each node says and what it asked the capability policy for are gathered per node and merged in plan order, so a build spread over four lanes reports exactly what the same build on one lane reports, node for node and sentence for sentence. How wide it spreads is read off the machine rather than guessed --- free memory divided by what a lane is allowed, one lane on a low battery that is not charging, half as many while a thermal zone is hot and one while it is scalding --- and read again as the build runs, so one that heats the phone narrows itself rather than being narrowed afterwards. A node writes down each step it passes, so a run that stops halfway starts again at the step it stopped at, and a node a previous run carried through is not run again at all unless its own work changed, which is what makes a build that was interrupted cheap to repeat.",
    },
    Subsystem {
        name: "Binary core",
        directive_section: 20,
        summary: "Bounded readers, patched writers, sections, tables and the CRC-32 \
                  and Adler-32 checksums the ZIP and DEX formats use.",
    },
    Subsystem {
        name: "XML reader",
        directive_section: 22,
        summary: "Enough XML to read resource files, with document type \
                  declarations and custom entities refused outright.",
    },
    Subsystem {
        name: "Resource engine",
        directive_section: 22,
        summary: "Values files parsed and validated, identifiers assigned from \
                  sorted order, references resolved and reference loops refused. \
                  The binary table is written and aapt2 reads every type, name \
                  and value back out of it.",
    },
    Subsystem {
        name: "Archive engine",
        directive_section: 23,
        summary: "The ZIP container an APK is: read, validated, and written deterministically. Entries are compressed with this build\u{2019}s own DEFLATE where it saves bytes, while the resource table and native libraries stay stored and aligned because the platform maps them in place. unzip extracts what this writes byte for byte and zipalign agrees on the alignment.",
    },
    Subsystem {
        name: "Toolchain lock",
        directive_section: 14,
        summary: "Pinned versions with provenance, verified against an observed \
                  environment.",
    },
    Subsystem {
        name: "Self integrity",
        directive_section: 29,
        summary: "A package reads its own bytes, recomputes the digest its signature records, and compares the signing certificate against the one the build expects. Repacking or re-signing turns the standing to TAMPERED.",
    },
    Subsystem {
        name: "Project scaffold",
        directive_section: 46,
        summary: "A project is a manifest at the root, one folder per chosen language with a starter file in each, and a resource folder holding a launcher-icon folder per density and a values folder per locale. The application's name lives in those values folders and the manifest points at it, so it is translated rather than fixed. Package name, application name, architectures, platform range, languages and locales are validated before anything is written.",
    },
    Subsystem {
        name: "Omni_Guard policy",
        directive_section: 29,
        summary: "Eleven rules every project must pass before a package is produced: no debuggable build, no cleartext by default, backup off, no unguarded exported component, no exported provider handing out URI grants, a platform floor of API 28, no high-risk permission, no shared user identity, no opting out of scoped storage, no census of every installed application, and no exported activity in a task another application can take over.",
    },
    Subsystem {
        name: "Build engine",
        directive_section: 23,
        summary: "A project becomes a signed package and a bundle with nothing borrowed: the security policy runs first, then the resource table is compiled from the project's launcher icons and values folders, the manifest encoded against it, the archive written and compressed, a certificate written, and the package signed. apksigner verifies the result and aapt2 reads the table back.",
    },
    Subsystem {
        name: "Key generation",
        directive_section: 30,
        summary: "RSA keys generated from the system random source with Miller-Rabin primality testing at 24 rounds, encoded as PKCS#8 and accepted by OpenSSL.",
    },
    Subsystem {
        name: "Certificate writer",
        directive_section: 25,
        summary: "Writes a self-signed X.509 v3 certificate with a random serial, proper UTC or generalised time, an RSA public key and the extensions a signing certificate carries -- subject and authority key identifiers over the SHA-1 of the key, basic constraints and key usage marked critical, and code signing as the extended use -- signed with SHA-256. OpenSSL reads back every one of them.",
    },
    Subsystem {
        name: "Big integers",
        directive_section: 30,
        summary: "Arbitrary-precision unsigned arithmetic: add, subtract, multiply, Knuth division and modular exponentiation, checked against arbitrary-precision reference values and against native arithmetic on twenty thousand random pairs. Exponentiation is a ladder: every rung does one multiplication and one squaring whatever the bit was, and which register each lands in is arithmetic on the bit rather than a jump on it.",
    },
    Subsystem {
        name: "RSA signing",
        directive_section: 25,
        summary: "RFC 8017 RSASSA-PKCS1-v1_5 signing with SHA-256 and SHA-512, over PKCS#1 and PKCS#8 private keys read with the Core's own DER reader. Signatures are byte-identical to the ones OpenSSL produces from the same key. Nothing signs unblinded: the message is multiplied by a factor drawn fresh for every signature, so the exponentiation runs on a number nobody outside chose, and the private exponent has a multiple of its order added to it, so two signings with one key walk different rungs. Every signature is then verified with the public exponent before it is handed back, which is what catches a fault in the Chinese-remainder halves.",
    },
    Subsystem {
        name: "Package signer",
        directive_section: 25,
        summary: "Writes APK Signature Scheme v2 and v3 blocks: signed data, signatures and public key, with the platform range in the v3 block, spliced ahead of the central directory with the end record repointed. apksigner verifies the v3 block at API 28 and the v2 block at API 27. Signing is in two halves that can be split apart: what has to be signed is handed out, and a signature made by something else entirely -- a key in Android's own keystore, or in this suite openssl -- is taken back and sealed in, which apksigner verifies just the same.",
    },
    Subsystem {
        name: "Symmetric cryptography",
        directive_section: 30,
        summary: "AES-256 in CBC with PKCS#7 padding, HMAC-SHA256 and HMAC-SHA512, and PBKDF2-HMAC-SHA256, each checked against the published vectors of FIPS-197, NIST SP 800-38A, RFC 4231 and RFC 6070. The substitution is computed in the field rather than read from a table, the reduction and the padding check are carried in masks rather than branches, and tags are compared to the last byte whatever the first one said, so what a key is changes what comes out and not how long it took or which memory was touched. All 256 bytes are held to the table the standard describes.",
    },
    Subsystem {
        name: "Developer keystore",
        directive_section: 25,
        summary: "A signing key the developer makes, named, dated and sealed under their own password as PBES2 (PBKDF2-HMAC-SHA256 at 210000 iterations, AES-256-CBC). OpenSSL opens what this writes and refuses the wrong password. The container carries a tag over every byte of itself, taken with a key derived from the one the sealed blob is encrypted under, and the tag is checked between the derivation and the decryption so that an altered file never reaches a decryption at all. It also carries a plain digest, which proves nothing against anybody but tells a mistyped password apart from a damaged file. Listing a key needs no password; the certificate inside is checked against the key before either is used. A shared 4096-bit key is written once on first use so a package can be built without making one first, and it is sealed to the device it was made on as well as to its password.",
    },
    Subsystem {
        name: "DEFLATE",
        directive_section: 24,
        summary: "The compressed stream RFC 1950 and RFC 1951 define, read and written: stored, fixed and dynamic Huffman blocks, LZ77 matching over a 32 kilobyte window, length-limited code construction by package merge, and the Adler-32 the container carries. An independent compressor\u{2019}s output reads back exactly here, and an independent reader accepts what this writes.",
    },
    Subsystem {
        name: "Bundle writer",
        directive_section: 22,
        summary: "Writes an Android App Bundle: a protobuf writer, the manifest and the resource table in aapt2 proto form with the platform identifier and typed value on every attribute, BundleConfig, and the archive around them. bundletool builds and signs a universal package from what this writes, and aapt2 reads that package back attribute for attribute, launcher icon included.",
    },
    Subsystem {
        name: "Image codec",
        directive_section: 22,
        summary: "Decodes a PNG to pixels and writes one back: every chunk checked against its own CRC-32, every filter and bit depth the format defines, and an encoder that picks the narrowest colour type, a palette when it wins, and the cheapest filter per line. 200 images written by other tools decode here and survive a write and a read unchanged, within a tenth of the size the tools that made them wrote. A nine-patch is compiled rather than carried: the guide border is read into stretchable runs, padding and per-region colours, written into the npTc chunk the platform reads, and the border is cropped away -- byte for byte what aapt2 writes for the same file.",
    },
    Subsystem {
        name: "Launcher icons",
        directive_section: 22,
        summary: "One image becomes twenty-three files: five densities from 48 to 192 pixels in a square and a round shape with an anti-aliased circular mask, an adaptive icon whose foreground sits inside the safe zone at five densities from 108 to 432, a monochrome layer of the same shape for a themed launcher, a background taken from the colour around the edge of the image, and the two XML drawables that put them together. aapt2 reports the adaptive icon as the application icon and reads back every layer.",
    },
    Subsystem {
        name: "Project workspace",
        directive_section: 46,
        summary: "Lists the projects on the device, walks a project's folders within bounds, reads and writes its text files, and moves and deletes what is in them through the same path rules the virtual filesystem uses, so nothing an edit does leaves the project folder. What is deleted goes to a trash that holds it for a day, with the path it came from written beside it, and is put back only where nothing has taken its place.",
    },
    Subsystem {
        name: "Git client",
        directive_section: 46,
        summary: "Reads a packfile the way the format writes one: the header, every object header, and every zlib stream inflated in turn, with both kinds of delta resolved in as many passes as the ordering needs. Every object is named by the SHA-1 over its own header and body, so a wrong byte gives a name that matches nothing. A commit is walked to its tree and the tree is written to disk, with the executable bit carried and any entry name that would leave its folder refused rather than written.",
    },
    Subsystem {
        name: "Binary XML",
        directive_section: 22,
        summary: "The binary XML an APK carries, written from parsed text and read back out of it: string pool in either encoding the platform writes, resource map, namespaces, elements and typed attribute values. aapt2 reads what this writes and agrees on every value, and this reads what aapt2 writes.",
    },
    Subsystem {
        name: "JVM class file reader",
        directive_section: 17,
        summary: "A class file read down to its members: constant pool with its \
                  two-slot longs, access flags, superclass, interfaces, fields, \
                  methods, attributes and Kotlin metadata -- checked field for \
                  field against javap on 50 classes this build produced.",
    },
    Subsystem {
        name: "Java compiler",
        directive_section: 16,
        summary: "Java source becomes class files and then dex, with nothing borrowed: a lexer and parser for the Java 25 grammar, names and types resolved against the platform jar and against the project's own classes, generics with inference and capture, poly expressions and overload resolution, inner and anonymous classes with the locals they capture, records, enums, sealed types, switch expressions, text blocks and try with resources, and a bytecode writer that computes its own stack map frames. javac is given the same source with every warning turned on, javap reads back the class files, and dexdump reads back the dex.",
    },
    Subsystem {
        name: "DEX writer",
        directive_section: 21,
        summary: "Writes a classes.dex: sorted string, type, prototype, field and method pools, class definitions with their interfaces and annotations, static and instance fields with the values a class declares for them, direct and virtual methods, code items with their exception handlers and register counts, and debug information carrying the line a bytecode address came from. More references than one dex can name become more than one dex. dexdump reads what this writes and the Core reads it back.",
    },
    Subsystem {
        name: "DEX reader",
        directive_section: 21,
        summary: "A classes.dex read down to the instructions in every method, with modified UTF-8 decoded properly and the file's own checksum and signature recomputed --- matched field for field against dexdump. The class data behind each definition gives the fields and methods a class declares and what each one is allowed to do; the code item behind each method gives its registers, the range each try covers and what each catch takes, and the instruction stream is walked by the whole instruction set, all two hundred and twenty-four opcodes, the three payload tables a switch or an array filler points at included, so that stepping through a body lands on instruction boundaries rather than guessing at them. An instruction that names something resolves it while it is read: a string to its text, a type to its name, a field to the class and type it belongs to, a method to its whole signature, so the reader can say what a method reads, writes and calls rather than only that a body is there. That is what lets a build check its own output: every instruction the writer emits is read back as the one it wrote, at the same stride, with the same registers.",
    },
    Subsystem {
        name: "SHA-1",
        directive_section: 30,
        summary: "FIPS 180-4 SHA-1, verified against the published NIST vectors, \
                  for one purpose: the DEX header's own signature field.",
    },
    Subsystem {
        name: "DER reader",
        directive_section: 30,
        summary: "A distinguished-encoding reader that refuses every alternative \
                  spelling BER allows: indefinite lengths, non-minimal lengths, \
                  padded integers and the high-tag-number form.",
    },
    Subsystem {
        name: "X.509 certificates",
        directive_section: 30,
        summary: "Reads a certificate's names, validity, serial, key size and \
                  algorithms, and fingerprints it with SHA-256.",
    },
    Subsystem {
        name: "Signature inspection",
        directive_section: 25,
        summary: "Finds the APK signing block, reads every scheme in it, \
                  recomputes the chunked SHA-256 or SHA-512 content digest over \
                  the package's own bytes, verifies the RSA signature over each \
                  signer's signed data, and checks that the key in the block is \
                  the key in the certificate it presents -- all matched against \
                  apksigner.",
    },
];

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum FailureClass {
    Success,
    Recoverable,
    UserError,
    ConfigurationError,
    ToolchainError,
    SecurityFailure,
    Corruption,
    ResourceExhaustion,
    InternalError,
    Cancellation,
}

impl FailureClass {
    pub const fn as_str(self) -> &'static str {
        match self {
            FailureClass::Success => "SUCCESS",
            FailureClass::Recoverable => "RECOVERABLE_FAILURE",
            FailureClass::UserError => "USER_ERROR",
            FailureClass::ConfigurationError => "CONFIGURATION_ERROR",
            FailureClass::ToolchainError => "TOOLCHAIN_ERROR",
            FailureClass::SecurityFailure => "SECURITY_FAILURE",
            FailureClass::Corruption => "CORRUPTION",
            FailureClass::ResourceExhaustion => "RESOURCE_EXHAUSTION",
            FailureClass::InternalError => "INTERNAL_ERROR",
            FailureClass::Cancellation => "CANCELLATION",
        }
    }
}

impl core::fmt::Display for FailureClass {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.as_str())
    }
}

pub mod json {
    #[derive(Debug, Default)]
    pub struct Writer {
        buf: String,
        needs_comma: Vec<bool>,
        roomy: bool,
    }

    impl Writer {
        pub fn new() -> Self {
            Writer {
                buf: String::with_capacity(1024),
                needs_comma: Vec::with_capacity(8),
                roomy: false,
            }
        }

        pub fn pretty() -> Self {
            Writer {
                roomy: true,
                ..Writer::new()
            }
        }

        fn indent(&mut self) {
            if !self.roomy {
                return;
            }
            self.buf.push('\n');
            for _ in 0..self.needs_comma.len() {
                self.buf.push_str("    ");
            }
        }

        fn separate(&mut self) {
            if self.needs_comma.is_empty() {
                return;
            }
            let last = self.needs_comma.len() - 1;
            if self.needs_comma[last] {
                self.buf.push(',');
            } else {
                self.needs_comma[last] = true;
            }
            self.indent();
        }

        fn named(&mut self, key: Option<&str>) {
            let Some(k) = key else {
                return;
            };
            self.write_escaped(k);
            self.buf.push(':');
            if self.roomy {
                self.buf.push(' ');
            }
        }

        pub fn begin_object(&mut self, key: Option<&str>) {
            self.separate();
            self.named(key);
            self.buf.push('{');
            self.needs_comma.push(false);
        }

        pub fn end_object(&mut self) {
            let filled = self.needs_comma.pop().unwrap_or(false);
            if filled {
                self.indent();
            }
            self.buf.push('}');
        }

        pub fn begin_array(&mut self, key: Option<&str>) {
            self.separate();
            self.named(key);
            self.buf.push('[');
            self.needs_comma.push(false);
        }

        pub fn end_array(&mut self) {
            let filled = self.needs_comma.pop().unwrap_or(false);
            if filled {
                self.indent();
            }
            self.buf.push(']');
        }

        pub fn field_str(&mut self, key: &str, value: &str) {
            self.separate();
            self.named(Some(key));
            self.write_escaped(value);
        }

        pub fn field_u64(&mut self, key: &str, value: u64) {
            self.separate();
            self.named(Some(key));
            self.buf.push_str(&value.to_string());
        }

        pub fn field_bool(&mut self, key: &str, value: bool) {
            self.separate();
            self.named(Some(key));
            self.buf.push_str(if value { "true" } else { "false" });
        }

        pub fn element_str(&mut self, value: &str) {
            self.separate();
            self.write_escaped(value);
        }

        pub fn finish(self) -> String {
            assert!(
                self.needs_comma.is_empty(),
                "omni_core::json::Writer::finish called with {} unclosed container(s)",
                self.needs_comma.len()
            );
            self.buf
        }

        fn write_escaped(&mut self, value: &str) {
            self.buf.push('"');
            for ch in value.chars() {
                match ch {
                    '"' => self.buf.push_str("\\\""),
                    '\\' => self.buf.push_str("\\\\"),
                    '\n' => self.buf.push_str("\\n"),
                    '\r' => self.buf.push_str("\\r"),
                    '\t' => self.buf.push_str("\\t"),
                    '\u{08}' => self.buf.push_str("\\b"),
                    '\u{0C}' => self.buf.push_str("\\f"),
                    c if (c as u32) < 0x20 => {
                        self.buf.push_str(&format!("\\u{:04x}", c as u32));
                    }
                    c => self.buf.push(c),
                }
            }
            self.buf.push('"');
        }
    }

    #[derive(Clone, Debug, PartialEq)]
    pub enum Json {
        Null,
        Bool(bool),
        Number(f64),
        Text(String),
        List(Vec<Json>),
        Object(Vec<(String, Json)>),
    }

    impl Json {
        pub fn get(&self, key: &str) -> Option<&Json> {
            match self {
                Json::Object(held) => held
                    .iter()
                    .find(|(name, _)| name == key)
                    .map(|(_, one)| one),
                _ => None,
            }
        }

        pub fn text(&self) -> Option<&str> {
            match self {
                Json::Text(held) => Some(held.as_str()),
                _ => None,
            }
        }

        pub fn integer(&self) -> Option<i64> {
            match self {
                Json::Number(held) if held.is_finite() => Some(*held as i64),
                _ => None,
            }
        }

        pub fn boolean(&self) -> Option<bool> {
            match self {
                Json::Bool(held) => Some(*held),
                _ => None,
            }
        }

        pub fn list(&self) -> Option<&[Json]> {
            match self {
                Json::List(held) => Some(held.as_slice()),
                _ => None,
            }
        }

        pub fn strings(&self) -> Vec<String> {
            self.list()
                .unwrap_or(&[])
                .iter()
                .filter_map(|one| one.text().map(|held| held.to_string()))
                .collect()
        }
    }

    struct Scan<'a> {
        held: &'a [u8],
        at: usize,
    }

    impl Scan<'_> {
        fn skip(&mut self) {
            while self.at < self.held.len() && self.held[self.at].is_ascii_whitespace() {
                self.at += 1;
            }
        }

        fn value(&mut self, deep: usize) -> Option<Json> {
            if deep > 64 {
                return None;
            }
            self.skip();
            let here = *self.held.get(self.at)?;
            match here {
                b'{' => self.object(deep),
                b'[' => self.array(deep),
                b'"' => self.text().map(Json::Text),
                b't' => self.word("true").then_some(Json::Bool(true)),
                b'f' => self.word("false").then_some(Json::Bool(false)),
                b'n' => self.word("null").then_some(Json::Null),
                _ => self.number(),
            }
        }

        fn word(&mut self, wanted: &str) -> bool {
            if self.held[self.at..].starts_with(wanted.as_bytes()) {
                self.at += wanted.len();
                return true;
            }
            false
        }

        fn object(&mut self, deep: usize) -> Option<Json> {
            self.at += 1;
            let mut out = Vec::new();
            loop {
                self.skip();
                match self.held.get(self.at)? {
                    b'}' => {
                        self.at += 1;
                        return Some(Json::Object(out));
                    }
                    b',' => {
                        self.at += 1;
                        continue;
                    }
                    b'"' => {}
                    _ => return None,
                }
                let name = self.text()?;
                self.skip();
                if *self.held.get(self.at)? != b':' {
                    return None;
                }
                self.at += 1;
                let held = self.value(deep + 1)?;
                out.push((name, held));
            }
        }

        fn array(&mut self, deep: usize) -> Option<Json> {
            self.at += 1;
            let mut out = Vec::new();
            loop {
                self.skip();
                match self.held.get(self.at)? {
                    b']' => {
                        self.at += 1;
                        return Some(Json::List(out));
                    }
                    b',' => {
                        self.at += 1;
                        continue;
                    }
                    _ => {}
                }
                out.push(self.value(deep + 1)?);
            }
        }

        fn text(&mut self) -> Option<String> {
            self.at += 1;
            let mut out = String::new();
            loop {
                let here = *self.held.get(self.at)?;
                self.at += 1;
                match here {
                    b'"' => return Some(out),
                    b'\\' => {
                        let escape = *self.held.get(self.at)?;
                        self.at += 1;
                        match escape {
                            b'"' => out.push('"'),
                            b'\\' => out.push('\\'),
                            b'/' => out.push('/'),
                            b'b' => out.push('\u{08}'),
                            b'f' => out.push('\u{0C}'),
                            b'n' => out.push('\n'),
                            b'r' => out.push('\r'),
                            b't' => out.push('\t'),
                            b'u' => {
                                let digits = self.held.get(self.at..self.at + 4)?;
                                self.at += 4;
                                let text = std::str::from_utf8(digits).ok()?;
                                let point = u32::from_str_radix(text, 16).ok()?;
                                out.push(char::from_u32(point)?);
                            }
                            _ => return None,
                        }
                    }
                    _ => {
                        let start = self.at - 1;
                        let mut stop = self.at;
                        while stop < self.held.len()
                            && self.held[stop] != b'"'
                            && self.held[stop] != b'\\'
                        {
                            stop += 1;
                        }
                        out.push_str(std::str::from_utf8(self.held.get(start..stop)?).ok()?);
                        self.at = stop;
                    }
                }
            }
        }

        fn number(&mut self) -> Option<Json> {
            let start = self.at;
            while self.at < self.held.len()
                && matches!(
                    self.held[self.at],
                    b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9'
                )
            {
                self.at += 1;
            }
            let text = std::str::from_utf8(self.held.get(start..self.at)?).ok()?;
            text.parse::<f64>().ok().map(Json::Number)
        }
    }

    pub fn read(text: &str) -> Option<Json> {
        let mut scan = Scan {
            held: text.as_bytes(),
            at: 0,
        };
        let held = scan.value(0)?;
        scan.skip();
        (scan.at >= scan.held.len()).then_some(held)
    }
}

pub mod diag {
    use crate::{json::Writer, FailureClass};

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Severity {
        Trace,
        Info,
        Warning,
        Error,
        Fatal,
    }

    impl Severity {
        pub const fn as_str(self) -> &'static str {
            match self {
                Severity::Trace => "TRACE",
                Severity::Info => "INFO",
                Severity::Warning => "WARNING",
                Severity::Error => "ERROR",
                Severity::Fatal => "FATAL",
            }
        }

        pub const fn is_blocking(self) -> bool {
            matches!(self, Severity::Error | Severity::Fatal)
        }
    }

    impl core::fmt::Display for Severity {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            f.write_str(self.as_str())
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Location {
        pub file: String,
        pub line: u32,
        pub column: u32,
    }

    impl Location {
        pub fn file(path: impl Into<String>) -> Self {
            Location {
                file: path.into(),
                line: 0,
                column: 0,
            }
        }

        pub fn at(path: impl Into<String>, line: u32, column: u32) -> Self {
            Location {
                file: path.into(),
                line,
                column,
            }
        }
    }

    impl core::fmt::Display for Location {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            match (self.line, self.column) {
                (0, _) => write!(f, "{}", self.file),
                (l, 0) => write!(f, "{}:{}", self.file, l),
                (l, c) => write!(f, "{}:{}:{}", self.file, l, c),
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Diagnostic {
        pub code: String,
        pub severity: Severity,
        pub class: FailureClass,
        pub origin: String,
        pub message: String,
        pub location: Option<Location>,
        pub context: Vec<String>,
        pub suggestion: Option<String>,
        pub related: Vec<String>,
    }

    impl Diagnostic {
        pub fn new(
            code: impl Into<String>,
            severity: Severity,
            class: FailureClass,
            origin: impl Into<String>,
            message: impl Into<String>,
        ) -> Self {
            Diagnostic {
                code: code.into(),
                severity,
                class,
                origin: origin.into(),
                message: message.into(),
                location: None,
                context: Vec::new(),
                suggestion: None,
                related: Vec::new(),
            }
        }

        pub fn with_location(mut self, location: Location) -> Self {
            self.location = Some(location);
            self
        }

        pub fn with_context(mut self, line: impl Into<String>) -> Self {
            self.context.push(line.into());
            self
        }

        pub fn with_class(mut self, class: FailureClass) -> Self {
            self.class = class;
            self
        }

        pub fn with_suggestion(mut self, suggestion: impl Into<String>) -> Self {
            self.suggestion = Some(suggestion.into());
            self
        }

        pub fn write_json(&self, w: &mut Writer) {
            w.begin_object(None);
            w.field_str("code", &self.code);
            w.field_str("severity", self.severity.as_str());
            w.field_str("class", self.class.as_str());
            w.field_str("origin", &self.origin);
            w.field_str("message", &crate::speech::sentence(&self.message));
            w.field_str("english", &self.message);
            if let Some(loc) = &self.location {
                w.begin_object(Some("location"));
                w.field_str("file", &loc.file);
                w.field_u64("line", loc.line as u64);
                w.field_u64("column", loc.column as u64);
                w.end_object();
            }
            w.begin_array(Some("context"));
            for line in &self.context {
                w.element_str(&crate::speech::detail(line));
            }
            w.end_array();
            if let Some(suggestion) = &self.suggestion {
                w.field_str("suggestion", &crate::speech::sentence(suggestion));
            }
            w.begin_array(Some("related"));
            for code in &self.related {
                w.element_str(code);
            }
            w.end_array();
            w.end_object();
        }

        pub fn write_body(&self, w: &mut Writer, done: &str, held: bool) {
            w.field_bool(done, held);
            w.field_str("code", &self.code);
            w.field_str("error", &crate::speech::sentence(&self.message));
            w.field_str("english", &self.message);
            if let Some(suggestion) = &self.suggestion {
                w.field_str("suggestion", &crate::speech::sentence(suggestion));
            }
            w.begin_array(Some("context"));
            for line in &self.context {
                w.element_str(&crate::speech::detail(line));
            }
            w.end_array();
        }
    }

    impl core::fmt::Display for Diagnostic {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            write!(
                f,
                "{} [{}]",
                self.code,
                crate::speech::sentence(self.severity.as_str())
            )?;
            if let Some(loc) = &self.location {
                write!(f, " {}", loc)?;
            }
            write!(f, "\n{}", crate::speech::sentence(&self.message))?;
            for line in &self.context {
                write!(f, "\n  {}", crate::speech::detail(line))?;
            }
            if let Some(s) = &self.suggestion {
                write!(
                    f,
                    "\n{}: {}",
                    crate::speech::sentence("Suggestion"),
                    crate::speech::sentence(s)
                )?;
            }
            Ok(())
        }
    }

    #[derive(Clone, Default, Debug)]
    pub struct Sink {
        entries: Vec<Diagnostic>,
    }

    impl Sink {
        pub fn new() -> Self {
            Sink {
                entries: Vec::new(),
            }
        }

        pub fn emit(&mut self, diagnostic: Diagnostic) {
            self.entries.push(diagnostic);
        }

        pub fn entries(&self) -> &[Diagnostic] {
            &self.entries
        }

        pub fn len(&self) -> usize {
            self.entries.len()
        }

        pub fn is_empty(&self) -> bool {
            self.entries.is_empty()
        }

        pub fn has_blocking(&self) -> bool {
            self.entries.iter().any(|d| d.severity.is_blocking())
        }

        pub fn max_severity(&self) -> Option<Severity> {
            self.entries.iter().map(|d| d.severity).max()
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_array(Some(key));
            for d in &self.entries {
                d.write_json(w);
            }
            w.end_array();
        }
    }
}

#[path = "Speech.rs"]
pub mod speech;

pub mod caps {
    use crate::json::Writer;

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Capability {
        FsRead,
        FsWrite,
        ProcessExec,
        Network,
        Internet,
        Crypto,
        KeyAccess,
        Jni,
        Native,
        TempStorage,
        Cache,
        Device,
        SensitiveOutput,
    }

    impl Capability {
        pub const fn as_str(self) -> &'static str {
            match self {
                Capability::FsRead => "FS_READ",
                Capability::FsWrite => "FS_WRITE",
                Capability::ProcessExec => "PROCESS_EXEC",
                Capability::Network => "NETWORK",
                Capability::Internet => "INTERNET",
                Capability::Crypto => "CRYPTO",
                Capability::KeyAccess => "KEY_ACCESS",
                Capability::Jni => "JNI",
                Capability::Native => "NATIVE",
                Capability::TempStorage => "TEMP_STORAGE",
                Capability::Cache => "CACHE",
                Capability::Device => "DEVICE",
                Capability::SensitiveOutput => "SENSITIVE_OUTPUT",
            }
        }

        pub const ALL: &'static [Capability] = &[
            Capability::FsRead,
            Capability::FsWrite,
            Capability::ProcessExec,
            Capability::Network,
            Capability::Internet,
            Capability::Crypto,
            Capability::KeyAccess,
            Capability::Jni,
            Capability::Native,
            Capability::TempStorage,
            Capability::Cache,
            Capability::Device,
            Capability::SensitiveOutput,
        ];

        pub const fn is_sensitive(self) -> bool {
            matches!(
                self,
                Capability::KeyAccess
                    | Capability::Crypto
                    | Capability::SensitiveOutput
                    | Capability::ProcessExec
                    | Capability::Network
                    | Capability::Internet
            )
        }
    }

    impl core::fmt::Display for Capability {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            f.write_str(self.as_str())
        }
    }

    #[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
    pub enum Decision {
        Grant,
        Deny,
    }

    impl Decision {
        pub const fn as_str(self) -> &'static str {
            match self {
                Decision::Grant => "GRANT",
                Decision::Deny => "DENY",
            }
        }

        pub const fn is_granted(self) -> bool {
            matches!(self, Decision::Grant)
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct AuditRecord {
        pub subject: String,
        pub capability: Capability,
        pub decision: Decision,
        pub reason: String,
    }

    #[derive(Clone, Debug)]
    pub struct Policy {
        name: String,
        granted: Vec<Capability>,
        audit: Vec<AuditRecord>,
    }

    impl Policy {
        pub fn new(name: impl Into<String>) -> Self {
            Policy {
                name: name.into(),
                granted: Vec::new(),
                audit: Vec::new(),
            }
        }

        pub fn name(&self) -> &str {
            &self.name
        }

        pub fn grant(&mut self, capability: Capability) -> &mut Self {
            if !self.granted.contains(&capability) {
                self.granted.push(capability);
                self.granted.sort();
            }
            self
        }

        pub fn revoke(&mut self, capability: Capability) -> &mut Self {
            self.granted.retain(|c| *c != capability);
            self
        }

        pub fn granted(&self) -> &[Capability] {
            &self.granted
        }

        pub fn request(&mut self, subject: &str, capability: Capability) -> Decision {
            let decision = if self.granted.contains(&capability) {
                Decision::Grant
            } else {
                Decision::Deny
            };
            let reason = match decision {
                Decision::Grant => format!("granted by policy '{}'", self.name),
                Decision::Deny => format!("not granted by policy '{}' (default deny)", self.name),
            };
            self.audit.push(AuditRecord {
                subject: subject.to_string(),
                capability,
                decision,
                reason,
            });
            decision
        }

        pub fn audit(&self) -> &[AuditRecord] {
            &self.audit
        }

        pub fn absorb(&mut self, records: Vec<AuditRecord>) {
            self.audit.extend(records);
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("name", &self.name);
            w.field_str("default", "DENY");
            w.begin_array(Some("granted"));
            for c in &self.granted {
                w.element_str(c.as_str());
            }
            w.end_array();
            w.begin_array(Some("audit"));
            for record in &self.audit {
                w.begin_object(None);
                w.field_str("subject", &record.subject);
                w.field_str("capability", record.capability.as_str());
                w.field_str("decision", record.decision.as_str());
                w.field_str("reason", &record.reason);
                w.field_bool("sensitive", record.capability.is_sensitive());
                w.end_object();
            }
            w.end_array();
            w.end_object();
        }
    }
}

pub mod plugin {
    use crate::caps::{Capability, Decision, Policy};
    use crate::diag::{Diagnostic, Severity};
    use crate::json::Writer;
    use crate::FailureClass;

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub struct Version {
        pub major: u16,
        pub minor: u16,
        pub patch: u16,
    }

    impl Version {
        pub const fn new(major: u16, minor: u16, patch: u16) -> Self {
            Version {
                major,
                minor,
                patch,
            }
        }

        pub const fn is_compatible_with(self, required: Version) -> bool {
            self.major == required.major
                && (self.minor > required.minor
                    || (self.minor == required.minor && self.patch >= required.patch))
        }
    }

    impl core::fmt::Display for Version {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            write!(f, "{}.{}.{}", self.major, self.minor, self.patch)
        }
    }

    #[derive(Clone, Copy, Debug)]
    pub struct Contract {
        pub id: &'static str,
        pub display_name: &'static str,
        pub version: Version,
        pub produces_artifacts: bool,
        pub summary: &'static str,
        pub inputs: &'static [&'static str],
        pub outputs: &'static [&'static str],
        pub required_capabilities: &'static [Capability],
        pub forbidden_capabilities: &'static [Capability],
        pub non_responsibilities: &'static [&'static str],
    }

    impl Contract {
        pub fn write_json(&self, w: &mut Writer) {
            w.begin_object(None);
            w.field_str("id", self.id);
            w.field_str("displayName", self.display_name);
            w.field_str("version", &self.version.to_string());
            w.field_bool("mayProduceArtifacts", self.produces_artifacts);
            w.field_str("summary", self.summary);
            w.begin_array(Some("inputs"));
            for i in self.inputs {
                w.element_str(i);
            }
            w.end_array();
            w.begin_array(Some("outputs"));
            for o in self.outputs {
                w.element_str(o);
            }
            w.end_array();
            w.begin_array(Some("requiredCapabilities"));
            for c in self.required_capabilities {
                w.element_str(c.as_str());
            }
            w.end_array();
            w.begin_array(Some("forbiddenCapabilities"));
            for c in self.forbidden_capabilities {
                w.element_str(c.as_str());
            }
            w.end_array();
            w.begin_array(Some("nonResponsibilities"));
            for n in self.non_responsibilities {
                w.element_str(n);
            }
            w.end_array();
            w.end_object();
        }
    }

    #[derive(Clone, Debug, Default)]
    pub struct Outcome {
        pub artifacts: Vec<String>,
    }

    #[derive(Debug)]
    pub struct Context<'a> {
        pub policy: &'a mut Policy,
        pub diagnostics: &'a mut crate::diag::Sink,
    }

    impl Context<'_> {
        pub fn require(&mut self, subject: &str, capability: Capability) -> Decision {
            self.policy.request(subject, capability)
        }
    }

    #[allow(unreachable_pub)]
    pub trait Plugin: Sync {
        fn contract(&self) -> &'static Contract;

        fn execute(&self, ctx: &mut Context<'_>) -> Result<Outcome, Diagnostic>;
    }

    pub fn unimplemented_diagnostic(contract: &Contract) -> Diagnostic {
        Diagnostic::new(
            "E0001",
            Severity::Error,
            FailureClass::InternalError,
            contract.id,
            format!("{} is not implemented here.", contract.display_name),
        )
        .with_context(format!("Contract version: {}", contract.version))
        .with_context(format!("Declared outputs: {}", contract.outputs.join(", ")))
        .with_suggestion(
            "This subsystem is declared, not built. Nothing was produced and \
             nothing should be expected from it.",
        )
    }

    static BUILTIN: &[&'static dyn Plugin] = &[
        &crate::compilers::kotlin::PLUGIN,
        &crate::compilers::java::PLUGIN,
        &crate::compilers::cpp::PLUGIN,
        &crate::compilers::rust::PLUGIN,
    ];

    #[derive(Clone, Copy)]
    pub struct Registry {
        plugins: &'static [&'static dyn Plugin],
    }

    impl Registry {
        pub fn builtin() -> Self {
            Registry { plugins: BUILTIN }
        }

        pub fn len(&self) -> usize {
            self.plugins.len()
        }

        pub fn is_empty(&self) -> bool {
            self.plugins.is_empty()
        }

        pub fn all(&self) -> &'static [&'static dyn Plugin] {
            self.plugins
        }

        pub fn find(&self, id: &str) -> Option<&'static dyn Plugin> {
            self.plugins.iter().copied().find(|p| p.contract().id == id)
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_array(Some(key));
            for p in self.plugins {
                p.contract().write_json(w);
            }
            w.end_array();
        }
    }
}

pub mod compiler {
    use crate::cache;
    use crate::caps::{Capability, Decision, Policy};
    use crate::diag::{Diagnostic, Severity, Sink};
    use crate::hash::{sha256, Digest};
    use crate::json::Writer;
    use crate::plugin::Contract;
    use crate::store::Store;
    use crate::FailureClass;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;

    fn fail(origin: &str, code: &str, message: impl Into<String>) -> Diagnostic {
        Diagnostic::new(
            code,
            Severity::Error,
            FailureClass::InternalError,
            origin,
            message,
        )
    }

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Abi {
        Arm64V8a,
    }

    impl Abi {
        pub const ALL: &'static [Abi] = &[Abi::Arm64V8a];

        pub const fn as_str(self) -> &'static str {
            match self {
                Abi::Arm64V8a => "arm64-v8a",
            }
        }

        pub fn parse(value: &str) -> Option<Abi> {
            Abi::ALL.iter().copied().find(|abi| abi.as_str() == value)
        }
    }

    pub const OLDEST_API: u32 = 30;
    pub const NEWEST_API: u32 = 37;

    pub const NEWEST_DESCRIBED_API: u32 = 37;

    pub const fn api_is_supported(level: u32) -> bool {
        level >= OLDEST_API && level <= NEWEST_API
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Identity {
        pub language: String,
        pub compiler: String,
        pub version: String,
        pub target: String,

        pub components: Vec<(String, String)>,
    }

    impl Identity {
        pub fn new(
            language: impl Into<String>,
            compiler: impl Into<String>,
            version: impl Into<String>,
            target: impl Into<String>,
        ) -> Identity {
            Identity {
                language: language.into(),
                compiler: compiler.into(),
                version: version.into(),
                target: target.into(),
                components: Vec::new(),
            }
        }

        pub fn with(mut self, name: impl Into<String>, value: impl Into<String>) -> Identity {
            self.components.push((name.into(), value.into()));
            self
        }

        pub fn canonical(&self) -> crate::canonical::Record {
            let components: Vec<(String, Vec<u8>)> = self
                .components
                .iter()
                .map(|(name, value)| (name.clone(), value.as_bytes().to_vec()))
                .collect();
            let mut record = crate::canonical::Record::new();
            record
                .text("language", &self.language)
                .text("compiler", &self.compiler)
                .text("version", &self.version)
                .text("target", &self.target)
                .table("components", &components);
            record
        }

        pub fn digest(&self) -> Digest {
            self.canonical().to_digest()
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("language", &self.language);
            w.field_str("compiler", &self.compiler);
            w.field_str("version", &self.version);
            w.field_str("target", &self.target);
            w.begin_array(Some("components"));
            for (name, value) in &self.components {
                w.begin_object(None);
                w.field_str("name", name);
                w.field_str("value", value);
                w.end_object();
            }
            w.end_array();
            w.field_str("digest", &self.digest().to_hex());
            w.end_object();
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub enum Reproducibility {
        Always,

        Given(Vec<String>),

        Unknown,
    }

    impl Reproducibility {
        pub fn as_str(&self) -> &'static str {
            match self {
                Reproducibility::Always => "ALWAYS",
                Reproducibility::Given(_) => "GIVEN",
                Reproducibility::Unknown => "UNKNOWN",
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Source {
        pub path: String,
        pub digest: Digest,
        pub bytes: u64,
    }

    impl Source {
        pub fn of(path: impl Into<String>, content: &[u8]) -> Source {
            Source {
                path: path.into(),
                digest: sha256(content),
                bytes: content.len() as u64,
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Request {
        pub sources: Vec<Source>,

        pub dependencies: Vec<Digest>,
        pub abi: Abi,
        pub api_level: u32,
        pub optimise: bool,
        pub debug_info: bool,
        pub options: Vec<(String, String)>,
    }

    impl Request {
        pub fn new(abi: Abi, api_level: u32) -> Request {
            Request {
                sources: Vec::new(),
                dependencies: Vec::new(),
                abi,
                api_level,
                optimise: true,
                debug_info: false,
                options: Vec::new(),
            }
        }

        pub fn with_source(mut self, source: Source) -> Request {
            self.sources.push(source);
            self
        }

        pub fn ordered_sources(&self) -> Vec<Source> {
            let mut sorted = self.sources.clone();
            sorted.sort_by(|left, right| {
                left.path
                    .cmp(&right.path)
                    .then_with(|| left.digest.cmp(&right.digest))
            });
            sorted
        }

        pub fn canonical(&self) -> crate::canonical::Record {
            let sources: Vec<Vec<u8>> = self
                .ordered_sources()
                .iter()
                .map(|source| {
                    let mut one = crate::canonical::Record::new();
                    one.text("path", &source.path)
                        .digest("digest", source.digest);
                    one.encode()
                })
                .collect();

            let dependencies: Vec<Vec<u8>> = {
                let mut sorted: Vec<Digest> = self.dependencies.clone();
                sorted.sort();
                sorted.dedup();
                sorted
                    .iter()
                    .map(|digest| digest.as_bytes().to_vec())
                    .collect()
            };

            let options: Vec<(String, Vec<u8>)> = self
                .options
                .iter()
                .map(|(name, value)| (name.clone(), value.as_bytes().to_vec()))
                .collect();

            let mut record = crate::canonical::Record::new();
            record
                .sequence("sources", &sources)
                .set("dependencies", &dependencies)
                .text("abi", self.abi.as_str())
                .number("api", u64::from(self.api_level))
                .flag("optimise", self.optimise)
                .flag("debugInfo", self.debug_info)
                .table("options", &options);
            record
        }
    }

    #[derive(Clone, Debug)]
    pub struct Probe {
        pub identity: Option<Identity>,
        pub reproducibility: Reproducibility,

        pub unavailable: Option<Diagnostic>,
    }

    impl Probe {
        pub fn usable(identity: Identity, reproducibility: Reproducibility) -> Probe {
            Probe {
                identity: Some(identity),
                reproducibility,
                unavailable: None,
            }
        }

        pub fn unavailable(why: Diagnostic) -> Probe {
            Probe {
                identity: None,
                reproducibility: Reproducibility::Unknown,
                unavailable: Some(why),
            }
        }

        pub fn is_usable(&self) -> bool {
            self.identity.is_some()
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_bool("usable", self.is_usable());
            w.field_str("reproducibility", self.reproducibility.as_str());
            if let Reproducibility::Given(conditions) = &self.reproducibility {
                w.begin_array(Some("reproducibleGiven"));
                for condition in conditions {
                    w.element_str(condition);
                }
                w.end_array();
            }
            match &self.identity {
                Some(identity) => identity.write_json(w, "identity"),
                None => {
                    if let Some(why) = &self.unavailable {
                        w.field_str("unavailable", &why.message);
                    }
                }
            }
            w.end_object();
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Expected {
        pub name: String,
        pub kind: Kind,
    }

    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
    pub enum Kind {
        JvmClass,
        Dex,
        Object,
        SharedObject,
        StaticLibrary,
        Resource,
        Metadata,
    }

    impl Kind {
        pub const fn as_str(self) -> &'static str {
            match self {
                Kind::JvmClass => "jvm.class",
                Kind::Dex => "dex",
                Kind::Object => "native.object",
                Kind::SharedObject => "native.shared",
                Kind::StaticLibrary => "native.static",
                Kind::Resource => "resource",
                Kind::Metadata => "metadata",
            }
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Plan {
        pub key: cache::Key,
        pub identity: Identity,
        pub expected: Vec<Expected>,
        pub reproducibility: Reproducibility,
    }

    impl Plan {
        pub fn key_for(identity: &Identity, request: &Request) -> cache::Key {
            let mut record = crate::canonical::Record::new();
            record
                .record("identity", &identity.canonical())
                .record("request", &request.canonical());
            cache::Key::from_digest(record.to_digest())
        }

        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("key", &self.key.to_hex());
            w.field_str("reproducibility", self.reproducibility.as_str());
            self.identity.write_json(w, "identity");
            w.begin_array(Some("expected"));
            for one in &self.expected {
                w.begin_object(None);
                w.field_str("name", &one.name);
                w.field_str("kind", one.kind.as_str());
                w.end_object();
            }
            w.end_array();
            w.end_object();
        }
    }

    #[derive(Clone, Debug)]
    pub struct Budget {
        pub seconds: u64,
        pub output_bytes: u64,
        cancelled: Arc<AtomicBool>,
    }

    impl Budget {
        pub fn of(seconds: u64, output_bytes: u64) -> Budget {
            Budget {
                seconds,
                output_bytes,
                cancelled: Arc::new(AtomicBool::new(false)),
            }
        }

        pub fn stopper(&self) -> Stopper {
            Stopper {
                flag: Arc::clone(&self.cancelled),
            }
        }

        pub fn is_cancelled(&self) -> bool {
            self.cancelled.load(Ordering::Relaxed)
        }
    }

    impl Default for Budget {
        fn default() -> Budget {
            Budget::of(300, 512 * 1024 * 1024)
        }
    }

    #[derive(Clone, Debug)]
    pub struct Stopper {
        flag: Arc<AtomicBool>,
    }

    impl Stopper {
        pub fn stop(&self) {
            self.flag.store(true, Ordering::Relaxed);
        }
    }

    #[derive(Clone, PartialEq, Eq, Debug)]
    pub struct Produced {
        pub name: String,
        pub kind: Kind,
        pub digest: Digest,
        pub bytes: u64,
    }

    #[derive(Clone, Debug)]
    pub struct Compiled {
        pub key: cache::Key,
        pub identity: Identity,
        pub produced: Vec<Produced>,
        pub reproducibility: Reproducibility,
    }

    impl Compiled {
        pub fn write_json(&self, w: &mut Writer, key: &str) {
            w.begin_object(Some(key));
            w.field_str("key", &self.key.to_hex());
            w.field_str("reproducibility", self.reproducibility.as_str());
            self.identity.write_json(w, "identity");
            w.begin_array(Some("produced"));
            for one in &self.produced {
                w.begin_object(None);
                w.field_str("name", &one.name);
                w.field_str("kind", one.kind.as_str());
                w.field_str("digest", &one.digest.to_hex());
                w.field_u64("bytes", one.bytes);
                w.end_object();
            }
            w.end_array();
            w.end_object();
        }
    }

    pub struct Session<'a> {
        origin: &'static str,
        store: &'a Store,
        policy: &'a mut Policy,
        diagnostics: &'a mut Sink,
        budget: Budget,
        started: std::time::Instant,
        offered: Vec<(String, Kind, Vec<u8>)>,
        spent: u64,
    }

    impl<'a> Session<'a> {
        pub fn new(
            origin: &'static str,
            store: &'a Store,
            policy: &'a mut Policy,
            diagnostics: &'a mut Sink,
            budget: Budget,
        ) -> Session<'a> {
            Session {
                origin,
                store,
                policy,
                diagnostics,
                budget,
                started: std::time::Instant::now(),
                offered: Vec::new(),
                spent: 0,
            }
        }

        pub fn store(&self) -> &Store {
            self.store
        }

        pub fn budget(&self) -> &Budget {
            &self.budget
        }

        pub fn require(&mut self, capability: Capability) -> Decision {
            self.policy.request(self.origin, capability)
        }

        pub fn report(&mut self, diagnostic: Diagnostic) {
            self.diagnostics.emit(diagnostic);
        }

        pub fn carry_on(&self) -> Result<(), Diagnostic> {
            if self.budget.is_cancelled() {
                return Err(Diagnostic::new(
                    "EX001",
                    Severity::Warning,
                    FailureClass::UserError,
                    self.origin,
                    "The compilation was stopped.",
                )
                .with_suggestion(
                    "Nothing it had produced was published, so nothing downstream can \
                     read half of it.",
                ));
            }
            let spent = self.started.elapsed().as_secs();
            if spent > self.budget.seconds {
                return Err(fail(
                    self.origin,
                    "EX002",
                    "The compilation ran past the time it was given.",
                )
                .with_context(format!("Spent: {spent} seconds"))
                .with_context(format!("Allowed: {} seconds", self.budget.seconds))
                .with_suggestion(
                    "Nothing it had produced was published. A build on a device shares \
                     that device with whatever the person is actually doing.",
                ));
            }
            Ok(())
        }

        pub fn offer(
            &mut self,
            name: impl Into<String>,
            kind: Kind,
            bytes: Vec<u8>,
        ) -> Result<(), Diagnostic> {
            self.carry_on()?;
            let name = name.into();
            if self.offered.iter().any(|(held, _, _)| *held == name) {
                return Err(fail(
                    self.origin,
                    "EX003",
                    "One compilation offered two things under one name.",
                )
                .with_context(format!("Name: {name}")));
            }
            self.spent += bytes.len() as u64;
            if self.spent > self.budget.output_bytes {
                return Err(fail(
                    self.origin,
                    "EX004",
                    "The compilation produced more than it was allowed to.",
                )
                .with_context(format!("Produced: {} bytes", self.spent))
                .with_context(format!("Allowed: {} bytes", self.budget.output_bytes)));
            }
            self.offered.push((name, kind, bytes));
            Ok(())
        }

        pub fn offered(&self) -> usize {
            self.offered.len()
        }

        pub fn commit(self, plan: &Plan) -> Result<Compiled, Diagnostic> {
            if plan.expected.len() != self.offered.len() {
                return Err(fail(
                    self.origin,
                    "EX005",
                    "The compilation did not produce what it planned to.",
                )
                .with_context(format!("Planned: {} outputs", plan.expected.len()))
                .with_context(format!("Produced: {} outputs", self.offered.len()))
                .with_suggestion(
                    "A plan is a promise about what will exist. Nothing is published \
                     from a compilation that did not keep it.",
                ));
            }

            let mut produced = Vec::with_capacity(self.offered.len());
            for (name, kind, bytes) in &self.offered {
                let promised = plan.expected.iter().find(|one| one.name == *name);
                let Some(promised) = promised else {
                    return Err(fail(
                        self.origin,
                        "EX006",
                        "The compilation produced something it never planned to.",
                    )
                    .with_context(format!("Name: {name}")));
                };
                if promised.kind != *kind {
                    return Err(fail(
                        self.origin,
                        "EX007",
                        "The compilation produced something other than what it planned.",
                    )
                    .with_context(format!("Name: {name}"))
                    .with_context(format!("Planned: {}", promised.kind.as_str()))
                    .with_context(format!("Produced: {}", kind.as_str())));
                }

                let digest = self.store.put(bytes)?;
                let back = self.store.get(digest)?;
                if back != *bytes {
                    return Err(Diagnostic::new(
                        "EX008",
                        Severity::Fatal,
                        FailureClass::Corruption,
                        self.origin,
                        "What was stored is not what was compiled.",
                    )
                    .with_context(format!("Name: {name}")));
                }
                produced.push(Produced {
                    name: name.clone(),
                    kind: *kind,
                    digest,
                    bytes: bytes.len() as u64,
                });
            }

            produced.sort_by(|left, right| left.name.cmp(&right.name));
            Ok(Compiled {
                key: plan.key,
                identity: plan.identity.clone(),
                produced,
                reproducibility: plan.reproducibility.clone(),
            })
        }
    }

    impl std::fmt::Debug for Session<'_> {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(
                f,
                "Session {{ origin: {}, offered: {} }}",
                self.origin,
                self.offered.len()
            )
        }
    }

    pub trait Compiler: Sync {
        fn contract(&self) -> &'static Contract;

        fn probe(&self) -> Probe;

        fn plan(&self, request: &Request) -> Result<Plan, Diagnostic>;

        fn compile(
            &self,
            plan: &Plan,
            request: &Request,
            session: Session<'_>,
        ) -> Result<Compiled, Diagnostic>;
    }

    pub fn check_contract(compiler: &dyn Compiler) -> Vec<String> {
        let contract = compiler.contract();
        let mut wrong = Vec::new();

        if contract.id.is_empty() || !contract.id.starts_with("omni.plugin.") {
            wrong.push(format!(
                "{}: an id must be omni.plugin.something",
                contract.id
            ));
        }
        for required in contract.required_capabilities {
            if contract.forbidden_capabilities.contains(required) {
                wrong.push(format!(
                    "{}: {} is both required and forbidden",
                    contract.id,
                    required.as_str()
                ));
            }
        }
        if contract.outputs.is_empty() {
            wrong.push(format!(
                "{}: a compiler that outputs nothing is not one",
                contract.id
            ));
        }
        if contract.non_responsibilities.is_empty() {
            wrong.push(format!(
                "{}: what a compiler does not do is part of what it is",
                contract.id
            ));
        }

        let probe = compiler.probe();
        match (&probe.identity, &probe.unavailable) {
            (Some(_), Some(_)) => wrong.push(format!(
                "{}: a probe cannot be both usable and unavailable",
                contract.id
            )),
            (None, None) => wrong.push(format!(
                "{}: a probe that found nothing has to say why",
                contract.id
            )),
            _ => {}
        }
        if let Some(identity) = &probe.identity {
            if identity.version.is_empty() {
                wrong.push(format!(
                    "{}: an identity without a version is not one",
                    contract.id
                ));
            }
            if contract.produces_artifacts && identity.language.is_empty() {
                wrong.push(format!(
                    "{}: an identity has to name its language",
                    contract.id
                ));
            }
        }

        let request = Request::new(Abi::Arm64V8a, OLDEST_API)
            .with_source(Source::of("probe.txt", b"anything at all"));
        if let (Ok(first), Ok(again)) = (compiler.plan(&request), compiler.plan(&request)) {
            if first.key != again.key {
                wrong.push(format!(
                    "{}: planning the same request twice gave two keys",
                    contract.id
                ));
            }
            if first.identity.digest() != again.identity.digest() {
                wrong.push(format!(
                    "{}: an identity that moves is not one",
                    contract.id
                ));
            }
        }

        let other = Request::new(Abi::Arm64V8a, NEWEST_API)
            .with_source(Source::of("probe.txt", b"anything at all"));
        if let (Ok(first), Ok(second)) = (compiler.plan(&request), compiler.plan(&other)) {
            if first.key == second.key {
                wrong.push(format!(
                    "{}: two platforms planned to the same key",
                    contract.id
                ));
            }
        }

        wrong
    }
}

