    const H0_160: [u32; 5] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];

    #[derive(Clone)]
    pub struct Sha1 {
        state: [u32; 5],
        block: [u8; 64],
        buffered: usize,
        length_bits: u64,
    }

    impl Default for Sha1 {
        fn default() -> Self {
            Self::new()
        }
    }

    impl Sha1 {
        pub const fn new() -> Self {
            Sha1 {
                state: H0_160,
                block: [0u8; 64],
                buffered: 0,
                length_bits: 0,
            }
        }

        pub fn update(&mut self, mut data: &[u8]) {
            self.length_bits = self.length_bits.wrapping_add((data.len() as u64) * 8);

            if self.buffered > 0 {
                let want = 64 - self.buffered;
                let take = want.min(data.len());
                self.block[self.buffered..self.buffered + take].copy_from_slice(&data[..take]);
                self.buffered += take;
                data = &data[take..];
                if self.buffered == 64 {
                    let block = self.block;
                    self.compress(&block);
                    self.buffered = 0;
                }
            }

            while data.len() >= 64 {
                let (block, rest) = data.split_at(64);
                let mut fixed = [0u8; 64];
                fixed.copy_from_slice(block);
                self.compress(&fixed);
                data = rest;
            }

            if !data.is_empty() {
                self.block[..data.len()].copy_from_slice(data);
                self.buffered = data.len();
            }
        }

        pub fn finish(mut self) -> Digest160 {
            let length_bits = self.length_bits;

            self.append_padding_byte(0x80);
            while self.buffered != 56 {
                self.append_padding_byte(0x00);
            }
            for byte in length_bits.to_be_bytes() {
                self.append_padding_byte(byte);
            }
            debug_assert_eq!(self.buffered, 0);

            let mut out = [0u8; 20];
            for (index, word) in self.state.iter().enumerate() {
                out[index * 4..index * 4 + 4].copy_from_slice(&word.to_be_bytes());
            }
            Digest160(out)
        }

        fn append_padding_byte(&mut self, byte: u8) {
            self.block[self.buffered] = byte;
            self.buffered += 1;
            if self.buffered == 64 {
                let block = self.block;
                self.compress(&block);
                self.buffered = 0;
            }
        }

        fn compress(&mut self, block: &[u8; 64]) {
            let mut w = [0u32; 80];
            for (index, chunk) in block.chunks_exact(4).enumerate() {
                w[index] = u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
            }
            for index in 16..80 {
                w[index] =
                    (w[index - 3] ^ w[index - 8] ^ w[index - 14] ^ w[index - 16]).rotate_left(1);
            }

            let [mut a, mut b, mut c, mut d, mut e] = self.state;

            for (index, word) in w.iter().enumerate() {
                let (f, k) = match index {
                    0..=19 => ((b & c) | ((!b) & d), 0x5a827999u32),
                    20..=39 => (b ^ c ^ d, 0x6ed9eba1),
                    40..=59 => ((b & c) | (b & d) | (c & d), 0x8f1bbcdc),
                    _ => (b ^ c ^ d, 0xca62c1d6),
                };
                let temp = a
                    .rotate_left(5)
                    .wrapping_add(f)
                    .wrapping_add(e)
                    .wrapping_add(k)
                    .wrapping_add(*word);
                e = d;
                d = c;
                c = b.rotate_left(30);
                b = a;
                a = temp;
            }

            for (slot, value) in self.state.iter_mut().zip([a, b, c, d, e]) {
                *slot = slot.wrapping_add(value);
            }
        }
    }

    pub fn sha1(data: &[u8]) -> Digest160 {
        let mut hasher = Sha1::new();
        hasher.update(data);
        hasher.finish()
    }

