    #[no_mangle]
    pub unsafe extern "C" fn omni_set_icon(
        root: *const c_char,
        source: *const c_char,
    ) -> *mut c_char {
        let result = catch_unwind(|| {
            let (Some(root), Some(source)) = (text_from(root), text_from(source)) else {
                return std::ptr::null_mut();
            };
            let mut w = crate::json::Writer::new();
            w.begin_object(None);
            match crate::scaffold::set_icon(&root, &source) {
                Ok(png) => {
                    w.field_bool("stored", true);
                    w.field_str("path", &crate::scaffold::icon_path(&root));
                    png.write_json(&mut w, "image");
                    w.field_bool("appliedToPackage", true);
                    w.field_str(
                        "note",
                        "The image is stored with the project and becomes the launcher icon of \
                         both the package and the bundle built from it. One image serves every \
                         screen; there is no density scaling here.",
                    );
                }
                Err(error) => write_failure(&mut w, "stored", &error),
            }
            w.end_object();
            hand_back(w)
        });
        result.unwrap_or(std::ptr::null_mut())
    }

    #[no_mangle]
    pub unsafe extern "C" fn omni_string_free(value: *mut c_char) {
        if value.is_null() {
            return;
        }
        let _ = catch_unwind(|| unsafe {
            drop(CString::from_raw(value));
        });
    }
